'use strict';
/**
 * The RouterOS connection-error CLASSIFIER, as a corpus generated by RUNNING the
 * live implementation.
 *
 * `src/routeros/classifyError.js` turns a driver error into the sentence the
 * Routers page shows when a router is offline (#92) and an operator hint that is
 * logged only. Without it every offline router says "Connection failed", which
 * is the string `OverviewSession.OnError` falls back to when nothing classified
 * — so the port needs this before the background pool is worth building.
 *
 * ---- THE ONE THING THAT CANNOT BE PORTED LITERALLY -------------------------
 *
 * The live matcher reads NODE's error shapes: a `.errno` that is `-111` or
 * `'CANTLOGIN'`, and a `RosException` name. Go's errors carry none of those —
 * `net.OpError` says "connection refused", "no route to host", "i/o timeout".
 *
 * So the CONTRACT here is condition → reason, not regex → reason. Each case
 * names the real-world condition, the input the LIVE side needs to reach that
 * branch, and the input a GO error would carry for the same condition. The live
 * implementation produces the expected strings; `classify_test.go` feeds the Go
 * spellings and must arrive at the same ones.
 *
 * A port that matched the live REGEXES instead would pass a naive test and
 * classify nothing at runtime, because no Go error contains "ECONNREFUSED".
 *
 *   MIKRODASH_SRC=../MikroDash node tools/classify-error-cases.js          # write
 *   MIKRODASH_SRC=../MikroDash node tools/classify-error-cases.js --check  # fail if stale
 */

const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.join(__dirname, '..');
const LIVE = path.resolve(process.env.MIKRODASH_SRC || path.join(ROOT, '..', 'MikroDash'));
const { classifyRosError } = require(path.join(LIVE, 'src', 'routeros', 'classifyError.js'));

const OPTS = { host: '198.51.100.1', port: '8729', user: 'dash', tls: false };
const TLS = { ...OPTS, tls: true };

/** An error shaped the way node's driver delivers one. */
function nodeErr(message, extra) {
  const e = new Error(message);
  return Object.assign(e, extra || {});
}

// condition            what the LIVE side sees          what a GO error says
const CASES = [
  ['host unreachable',  nodeErr('connect EHOSTUNREACH'), 'dial tcp 198.51.100.1:8729: connect: no route to host', OPTS],
  ['net unreachable',   nodeErr('connect ENETUNREACH'),  'dial tcp 198.51.100.1:8729: connect: network is unreachable', OPTS],
  ['errno host unreach', nodeErr('RosException', { errno: '-113' }), 'dial tcp: connect: no route to host', OPTS],
  ['refused',           nodeErr('connect ECONNREFUSED'), 'dial tcp 198.51.100.1:8729: connect: connection refused', OPTS],
  ['errno refused',     nodeErr('RosException', { errno: '-111' }), 'dial tcp: connect: connection refused', OPTS],
  ['refused over tls',  nodeErr('connect ECONNREFUSED'), 'dial tcp: connect: connection refused', TLS],
  ['timed out',         nodeErr('connect ETIMEDOUT'),    'dial tcp 198.51.100.1:8729: i/o timeout', OPTS],
  ['timed out, worded', nodeErr('Socket timed out'),     'read tcp: i/o timeout', OPTS],
  ['errno timed out',   nodeErr('RosException', { errno: '-110' }), 'dial tcp: i/o timeout', OPTS],
  ['host not found',    nodeErr('getaddrinfo ENOTFOUND'), 'dial tcp: lookup rtr.invalid: no such host', OPTS],
  ['reset',             nodeErr('read ECONNRESET'),      'read tcp: connection reset by peer', OPTS],
  ['certificate',       nodeErr('self signed certificate in chain'), 'tls: failed to verify certificate: x509: certificate signed by unknown authority', TLS],
  ['auth',              nodeErr('invalid user name or password'), 'from RouterOS device: cannot log in', OPTS],
  ['auth, login word',  nodeErr('login failed'),         'cannot log in', OPTS],
  ['auth by errno',     nodeErr('RosException', { errno: 'CANTLOGIN' }), 'cannot log in', OPTS],
  // NODE'S `RosException` IS THE PORT'S `*Trap`. Both mean "the device answered
  // with an error" rather than "the socket failed", which is the distinction the
  // branch turns on. `goTrap` tells the Go test to build one instead of a plain
  // error; there is no message to match on, and matching one would be inventing
  // a Go spelling for a node type.
  //
  // Neither carries an errno on the Go side, so the corpus deliberately uses
  // `errno: ''` — the live branch then omits its `[errno]` bracket and the two
  // sides agree exactly, rather than the port having to fabricate a number.
  ['ros exception',     nodeErr('RosException', { errno: '' }), { goTrap: true }, OPTS],
  ['ros exception, tls', nodeErr('RosException', { errno: '' }), { goTrap: true }, TLS],
  // AMBIGUOUS ON PURPOSE: the message names TWO conditions, so it is the only
  // kind of case that can observe branch ORDER. The live chain tests refused
  // BEFORE timeout, so "Connection refused" wins on both sides. Without this the
  // two branches are disjoint in every case, reordering them changes nothing,
  // and the header's claim that order is part of the contract is untested — a
  // mutation that swapped them passed a full corpus.
  ['refused AND timed out', nodeErr('connect ECONNREFUSED after ETIMEDOUT'),
    'dial tcp 198.51.100.1:8729: connect: connection refused (after i/o timeout)', OPTS],
  // And the pair the live chain resolves the other way: unreachable is tested
  // before refused, so this one is NOT "Connection refused".
  ['unreachable AND refused', nodeErr('connect EHOSTUNREACH then ECONNREFUSED'),
    'dial tcp: connect: no route to host (connection refused)', OPTS],
  // NOTHING MATCHES. `classified` is false and the reason is still the raw
  // message, which the header warns must never reach a browser unsanitised.
  ['unclassified',      nodeErr('something nobody predicted'), 'something nobody predicted', OPTS],
];

const out = CASES.map(([name, err, goInput, opts]) => {
  const got = classifyRosError(err, opts);
  const trap = typeof goInput === 'object' && goInput !== null && goInput.goTrap;
  return {
    name,
    goMessage: trap ? '' : goInput,
    goTrap: !!trap,
    tls: !!opts.tls,
    host: opts.host, port: opts.port, user: opts.user,
    reason: got.reason,
    hint: got.hint,
    classified: got.classified,
  };
});

// BELIEVABILITY: a corpus where nothing classified would be a corpus of the
// fallback, and the Go side could pass it by classifying nothing at all.
const yes = out.filter((c) => c.classified).length;
assert.ok(yes >= CASES.length - 1,
  'only ' + yes + ' of ' + CASES.length + ' cases classified — the live module is not being ' +
  'reached, or the inputs no longer match its branches');
assert.equal(out[out.length - 1].classified, false,
  'the unclassified case classified — then nothing here tests the fallback');
assert.ok(new Set(out.map((c) => c.reason)).size >= 8,
  'the corpus collapsed onto too few distinct reasons to discriminate');

const FILE = path.join(ROOT, 'testdata', 'classify-error-cases.json');
const text = JSON.stringify(out, null, 2) + '\n';
if (process.argv.includes('--check')) {
  const have = fs.existsSync(FILE) ? fs.readFileSync(FILE, 'utf8') : '';
  if (have !== text) {
    console.error('classify-error-cases: STALE — regenerate with `node tools/classify-error-cases.js`');
    process.exit(1);
  }
  console.log('classify-error-cases: ' + out.length + ' cases current');
} else {
  fs.writeFileSync(FILE, text);
  console.log('classify-error-cases: wrote ' + out.length + ' cases (' + yes + ' classified)');
}
